class TaskProcessor {
    constructor() {
        this.tasks = [];
        this.nextTaskId = 1;
    }

    // This method handles creating a task, assigning it, and logging. Too many responsibilities!
    createAndAssignTask(description, assignee) {
        if (!description || !assignee) {
            console.error("Task description and assignee are required.");
            return null;
        }
        const taskId = this.nextTaskId++;
        const task = {
            id: taskId,
            description: description,
            assignee: assignee,
            status: "Pending"
        };
        this.tasks.push(task);
        this.logEvent(`Task ${taskId}: '${description}' assigned to ${assignee}. Status: ${task.status}`);
        return task;
    }

    completeTask(taskId) {
        const task = this.tasks.find(t => t.id === taskId);
        if (task) {
            task.status = "Completed";
            this.logEvent(`Task ${taskId}: '${task.description}' completed by ${task.assignee}.`);
            return true;
        }
        this.logEvent(`Task ${taskId} not found for completion.`);
        return false;
    }

    logEvent(message) {
        // TODO: This logging responsibility should be in a separate class.
        console.log(`[LOG] ${new Date().toISOString()} - ${message}`);
    }

    listAllTasks() {
        return this.tasks;
    }
}

