class Task {
    constructor(id, description, assignee) {
        if (!description || !assignee) {
            throw new Error("Task description and assignee are required.");
        }
        this.id = id;
        this.description = description;
        this.assignee = assignee;
        this.status = "Pending";
    }

    markAsCompleted() {
        this.status = "Completed";
    }
}

class TaskLogger {
    log(message) {
        console.log(`[LOG] ${new Date().toISOString()} - ${message}`);
    }
}

class TaskScheduler {
    constructor(taskLogger) {
        this.tasks = [];
        this.nextTaskId = 1;
        this.logger = taskLogger;
    }

    addTask(description, assignee) {
        try {
            const task = new Task(this.nextTaskId++, description, assignee);
            this.tasks.push(task);
            this.logger.log(`Task ${task.id}: '${task.description}' assigned to ${task.assignee}. Status: ${task.status}`);
            return task;
        } catch (error) {
            this.logger.log(`Failed to add task: ${error.message}`);
            return null;
        }
    }

    completeTask(taskId) {
        const task = this.tasks.find(t => t.id === taskId);
        if (task) {
            task.markAsCompleted();
            this.logger.log(`Task ${taskId}: '${task.description}' completed by ${task.assignee}.`);
            return true;
        }
        this.logger.log(`Task ${taskId} not found for completion.`);
        return false;
    }

    listTasks() {
        return [...this.tasks];
    }
}

// Example Usage:
const logger = new TaskLogger();
const scheduler = new TaskScheduler(logger);

scheduler.addTask("Review code for project X", "Bob");
scheduler.addTask("Update documentation for API", "Alice");
scheduler.completeTask(1);

console.log("Current Tasks:");
scheduler.listTasks().forEach(task => console.log(`- ID: ${task.id}, Desc: ${task.description}, Assignee: ${task.assignee}, Status: ${task.status}`));

